import json
import sys

sys.path.insert(0, "src")
from packaging.specifiers import Specifier, SpecifierSet

observed = {}
for name, original, changes in (
    ("split_operator", Specifier(">=1"), {"operator": "<", "version": "=2"}),
    ("integer_version", Specifier("==1"), {"version": 2}),
    ("single_policy", Specifier("==1"), {"prereleases": "invalid"}),
    ("set_policy", SpecifierSet("==1"), {"prereleases": "invalid"}),
    ("equivalent_set", SpecifierSet(">=1"), {"specifiers": ">=1"}),
):
    try:
        result = original.__replace__(**changes)
    except (AttributeError, TypeError, ValueError) as exc:
        observed[name] = {"exception": type(exc).__name__}
    else:
        observed[name] = {"text": str(result), "policy": result.prereleases, "same": result is original}
print(json.dumps(observed))

import json
import pytest
p = pytest.param(7, id="example")
record={"values":list(p.values),"marks":list(p.marks),"id":p.id,"tuple_instance":isinstance(p,tuple)}
try:
    values, marks, ident = p
    record["unpacked"]=[list(values),list(marks),ident]
except TypeError as exc:
    record["unpack_error"]=type(exc).__name__
print(json.dumps(record))
